import itertools
from pathlib import Path
import numpy as np
import pandas as pd

# 1. Institutional Path Setup & Data Loading
ROOT_DIR = Path(__file__).resolve().parent
# Make sure this matches the file generated by your data_fetcher.py
DATA_PATH = ROOT_DIR / "data" / "SPY_1Day_180d.parquet" 

def run_grid_search():
    print("=== INSTITUTIONAL PARAMETER GRID SEARCH ===")
    
    if not DATA_PATH.exists():
        print(f"❌ Error: Cache file not found at {DATA_PATH}.")
        print("Run data_fetcher.py first to populate the /data cache.")
        return

    # Load cached Parquet file to avoid Alpaca API rate limits
    df_raw = pd.read_parquet(DATA_PATH)
    if "close" not in df_raw.columns:
        raise ValueError("Parquet file must contain a 'close' column.")

    close_series = df_raw["close"].dropna()

    # 2. Define the Parameter Matrix
    # We test Short SMAs against Long SMAs alongside dynamic stop-loss margins
    short_windows = [10, 15, 20]
    long_windows = [40, 50, 60]
    stop_losses = [0.01, 0.02, 0.03]  # 1%, 2%, 3% cutoffs
    friction_bps = 0.0008 # 8 bps round-trip transaction cost (spread + slippage)

    results = []
    total_iterations = len(short_windows) * len(long_windows) * len(stop_losses)
    print(f"🔄 Scanning {total_iterations} combinations across {len(close_series)} bars...\n")

    # 3. Vectorized Evaluation Engine
    for short_w, long_w, stop in itertools.product(short_windows, long_windows, stop_losses):
        # Skip illogical crossovers
        if short_w >= long_w:
            continue

        df = pd.DataFrame({"close": close_series})
        
        # Calculate Technical Indicators
        df["SMA_fast"] = df["close"].rolling(window=short_w).mean()
        df["SMA_slow"] = df["close"].rolling(window=long_w).mean()

        # Raw Signal Generation
        df["Signal"] = 0
        df.loc[df["SMA_fast"] > df["SMA_slow"], "Signal"] = 1
        df.loc[df["SMA_fast"] < df["SMA_slow"], "Signal"] = -1

        # Shift position by 1 day to mathematically eliminate Look-Ahead Bias
        df["Position"] = df["Signal"].shift(1)

        # Calculate Gross Returns
        df["Market_Return"] = np.log(df["close"] / df["close"].shift(1))
        df["Gross_Strategy_Return"] = df["Position"] * df["Market_Return"]
        
        # Apply Stop-Loss Constraint (Simplified vectorized clipping)
        df["Gross_Strategy_Return"] = np.where(
            df["Gross_Strategy_Return"] < -stop, 
            -stop, 
            df["Gross_Strategy_Return"]
        )

        # Deduct Friction (Spread & Slippage applied only when position changes)
        df["Turnover"] = df["Position"].diff().abs().fillna(0)
        df["Net_Strategy_Return"] = df["Gross_Strategy_Return"] - (df["Turnover"] * friction_bps)

        # Filter out the initial rolling warm-up rows
        clean_returns = df["Net_Strategy_Return"].dropna()

        if len(clean_returns) < 30 or clean_returns.std() == 0:
            continue

        # 4. Calculate Institutional Risk Metrics
        # Metric 1: Annualized Sharpe Ratio (252 trading days)
        sharpe = (clean_returns.mean() / clean_returns.std()) * np.sqrt(252)

        # Metric 2: Total Compounded Return
        cum_returns = np.exp(clean_returns.cumsum())
        total_return = cum_returns.iloc[-1] - 1

        # Metric 3: Maximum Drawdown (MDD)
        rolling_peak = np.maximum.accumulate(cum_returns)
        drawdowns = (cum_returns - rolling_peak) / rolling_peak
        max_drawdown = drawdowns.min()

        # Metric 4: Win Rate
        active_days = (clean_returns != 0).sum()
        win_rate = (clean_returns > 0).sum() / active_days if active_days > 0 else 0.0

        results.append({
            "Fast_SMA": short_w,
            "Slow_SMA": long_w,
            "Stop_Loss": f"{stop * 100:.1f}%",
            "Total_Return": f"{total_return * 100:.2f}%",
            "Win_Rate": f"{win_rate * 100:.1f}%",
            "Max_Drawdown": f"{max_drawdown * 100:.2f}%",
            "Sharpe_Ratio": round(sharpe, 2)
        })

    # 5. Rank and Display Performance
    results_df = pd.DataFrame(results)
    if not results_df.empty:
        # Rank by highest risk-adjusted return (Sharpe)
        results_df = results_df.sort_values(by="Sharpe_Ratio", ascending=False).reset_index(drop=True)
        top_5 = results_df.head(5)
        
        print("🏆 TOP 5 PARAMETER COMBINATIONS (Friction-Adjusted) 🏆")
        print(top_5.to_string(index=False))
        
        # Benchmark Checks
        best_sharpe = top_5.iloc[0]["Sharpe_Ratio"]
        best_dd = float(top_5.iloc[0]["Max_Drawdown"].replace('%', ''))
        
        print("\n--- BENCHMARK DIAGNOSTICS ---")
        if best_sharpe >= 1.5 and best_dd >= -15.0:
            print("✅ PASSED: Sharpe > 1.5 and Drawdown is better than -15%.")
            print("Ready to update `live_paper_trader.py` with the top-ranked parameters.")
        else:
            print("⚠️ WARNING: Best model failed institutional benchmarks (Sharpe < 1.5 or Drawdown > 15%).")
            print("Do not deploy. Adjust parameter grid or strategy logic.")
    else:
        print("❌ No valid results found. Verify your Parquet data coverage.")

if __name__ == "__main__":
    run_grid_search()